/**
 * Obtiene la carta correspondiente para una obra y un número de carta (1 a 5).
 * Si no existiera, fallback seguro a la carta 1 de 'PP'.
 */
export function getCardForWork(workCode: WorkCode, cardNumber: number): WorkCardDef {
  const workCards = WORKS_CARDS_MAP[workCode] || WORKS_CARDS_MAP.PP;
  const clampedNum = Math.min(Math.max(cardNumber, 1), 5);
  return workCards[clampedNum] || workCards[1] || WORKS_CARDS_MAP.PP[1];
}

export function getAllCardsForWork(workCode: WorkCode): WorkCardDef[] {
  const workCards = WORKS_CARDS_MAP[workCode] || WORKS_CARDS_MAP.PP;
  return Object.values(workCards);
}
